# If spec is a percentage string like "50%"
if spec.endswith('%'):
    try:
        percent = float(spec[:-1])
        if percent < 0:
            # Negative percentage means complement
            val = int(round(num_clauses * (1 + percent / 100)))
        else:
            val = int(round(num_clauses * (percent / 100)))
        return min(num_clauses, max(0, val))
    except ValueError:
