# If spec contains conditional expressions like "2<-25% 9<-3"
# Parse multiple conditions separated by spaces
conditions = spec.split()
for cond in conditions:
    if '<' in cond:
        left, right = cond.split('<', 1)
        try:
            left_val = int(left)
        except ValueError:
            continue
        # Evaluate right side which can be percentage or integer
        right_val = None
        if right.endswith('%'):
            try:
                percent = float(right[:-1])
                if percent < 0:
                    right_val = int(round(num_clauses * (1 + percent / 100)))
                else:
                    right_val = int(round(num_clauses * (percent / 100)))
            except ValueError:
                continue
        else:
            try:
                right_val = int(right)
            except ValueError:
                continue
        if num_clauses <= left_val:
            return min(num_clauses, max(0, right_val))

